/* eslint-disable @typescript-eslint/no-explicit-any */
import { SymbolKind, SymbolStatus } from "./symbols";
export const context = {
    target: "mongodb",
    table: {},
};
export function define(details) {
    if (!("name" in details)) {
        throw new Error(`Found unnamed top-level definition`);
    }
    const { name } = details;
    if (name in context.table) {
        throw new Error(`Redefinition of '${name}'`);
    }
    if (!("type" in details)) {
        throw new Error(`${details.name} needs a 'type'`);
    }
    context.table[name] = {
        name,
        referenceCount: 0,
        raw: details,
        visibility: "public",
        status: SymbolStatus.Unresolved,
        type: (() => {
            switch (details.type) {
                case "entity":
                    return SymbolKind.Entity;
                case "enum":
                    return SymbolKind.Enum;
                case "object":
                    return SymbolKind.Object;
                default: {
                    throw new Error(`Unkown type '${details.type}' for '${details.name}'`);
                }
            }
        })(),
    };
}
